import "./text.css";

import type { ComponentProps, ElementType } from "react";
import { cx } from "./cx";

type TextTone = "heading" | "body" | "sub";

type TextTag = "p" | "span" | "div" | "h1" | "h2" | "h3" | "h4" | "strong";

export type TextProps = Omit<ComponentProps<"p">, "as"> & {
  as?: TextTag;
  tone?: TextTone;
};

export function Text({
  as: Tag = "p",
  tone = "body",
  className,
  ...rest
}: TextProps) {
  const Element = Tag as ElementType;
  return (
    <Element className={cx("ns-text", className)} data-tone={tone} {...rest} />
  );
}

@layer components {
  .ns-text {
    margin: 0;
    font: inherit;
    line-height: var(--leading, 1.5625);
  }

  .ns-text[data-tone="heading"] {
    color: var(--text-heading, #111);
    font-size: var(--type-lg, 1.25rem);
    font-weight: var(--weight-medium, 500);
    line-height: var(--leading-tight, 1.25);
  }

  .ns-text[data-tone="body"] {
    color: var(--text-body, #444);
    font-size: var(--type-md, 1rem);
  }

  .ns-text[data-tone="sub"] {
    color: var(--text-sub, #767676);
    font-size: var(--type-sm, 0.8rem);
  }
}
